"""Render original design recipes and a self-contained offline catalogue.

Input: design-atlas.json. Output: PATTERN-CATALOG.md, DESIGN-SOURCES.md,
design-atlas.html, atlas-verification.json. No third-party assets or runtime libraries.
"""
from pathlib import Path
from html import escape as e
import json
import hashlib
from bs4 import BeautifulSoup

ROOT = Path(__file__).resolve().parent
DATA = json.loads((ROOT / 'design-atlas.json').read_text())
PATTERNS, THEMES, SOURCES = (DATA[k] for k in ('patterns', 'themes', 'sources'))
S = {x['id']: x for x in SOURCES}

def source_links(ids, html=False):
    if html:
        return ' · '.join(f'<a href="{e(S[i]["url"])}">{e(S[i]["name"])}</a>' for i in ids)
    return ' · '.join(f'[{S[i]["name"]}]({S[i]["url"]})' for i in ids)

def write_markdown():
    text = ['# Pattern catalogue', '', 'Version 2.0 · 18 September 2026', '',
            '120 original house recipes; 78 mapped to the observed 21st.dev directory categories, plus 42 extended patterns. These are design options, not mandatory features or tested integrations. Cost labels are relative implementation/verification estimates, not benchmarks. Use with the Design Atlas and rulebook chapters 37–40. Source links are discovery or foundation references; they do not assert that a source implements the complete recipe.', '']
    group = None
    for p in PATTERNS:
        if p['group'] != group:
            group = p['group']; text += [f'## {group}', '']
        text += [f'### {p["id"]} · {p["name"]}', '',
                 f'**Category:** {p["category"] or p["group"]} · **Estimated effort:** {p["cost"]}', '',
                 f'**Variants:** {p["variants"]}', '', f'**Use when:** {p["use"]}', '',
                 f'**Acceptance concern:** {p["guard"]}', '', f'**Fallback:** {p["fallback"]}', '',
                 f'**Explore:** {source_links(p["sources"])} · **Maturity:** {p["maturity"]}', '']
    text += ['## Art directions', '', 'Mood swatches are not verified UI contrast pairs. Each direction needs semantic light/dark tokens and actual content checks.', '']
    for t in THEMES:
        text += [f'### {t["id"]} · {t["name"]}', '',f'**Fits:** {t["use"]}', '',
                 f'**Composition:** {t["composition"]}', '',f'**Palette:** {t["palette"]} · Mood swatches: '+', '.join(t['swatches']), '',
                 f'**Type and motion:** {t["type_motion"]}', '',f'**Watch:** {t["guard"]}', '']
    (ROOT/'PATTERN-CATALOG.md').write_text('\n'.join(text))
    text=['# Design research source register', '', 'Public-source research checked 18 September 2026. This register records the extent of inspection; it is not a list of certified suppliers. Recheck selected versions, terms, and implementation guidance at adoption. No paid assets or third-party implementations are bundled.', '',
          'The catalogue recipes are original synthesis. Sources below supply discovery, vocabulary, implementation guidance, or rights information. Source inspection does not mean all linked demos were tested. Original atlas specimens are separately labeled as local demonstrations.', '']
    for s in SOURCES:
        text += [f'## {s["id"]} · {s["name"]}', '',f'[{s["name"]}]({s["url"]}) · {s["group"]}', '',s['note'], '', f'Checked: {s["checked"]} · Extent: {s["status"]}', '']
    text+=['## Coverage and limitations', '',
           'The 21st.dev category inventory covers the 29 Marketing Blocks and 49 UI Components labels visible in its public directory. Separators and extended workflow/art families are added independently. No changing item counts are asserted. The other sites are a curated selection, not the complete internet.', '',
           'React Bits was inspected through its official repository. Origin UI redirected to coss ui. Awwwards, Refero, Motion Primitives, Rive accessibility, the initial Carbon URL, and Three.js responsive documentation were unavailable or insufficiently readable in this pass; they are not counted as inspected sources. The current Carbon motion page was subsequently located and read. Paid individual Mobbin flows were not reviewed.', '',
           'The main handbook retains its earlier sources. The 34 entries here include overlapping source URLs, so do not add the two source counts and call the result unique websites.', '']
    (ROOT/'DESIGN-SOURCES.md').write_text('\n'.join(text))

